import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const validId = id => typeof id === 'string' && id.length > 0;

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Expected an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (!job || typeof job !== 'object' || Array.isArray(job) ||
        !validId(job.id) || !Array.isArray(job.deps) ||
        !['pending', 'succeeded', 'failed'].includes(job.state)) {
      throw new Error('Malformed job');
    }
    if (jobs.has(job.id)) throw new Error('Duplicate job ID');
    const deps = new Set();
    for (const dep of job.deps) {
      if (!validId(dep) || deps.has(dep)) throw new Error('Invalid or duplicate dependency');
      deps.add(dep);
    }
    jobs.set(job.id, { id: job.id, deps, state: job.state, children: [], causes: new Set(), indegree: deps.size });
  }
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error('Unknown dependency');
      jobs.get(dep).children.push(job.id);
    }
  }

  // Sort descending so pop always selects the smallest currently available ID.
  const available = [...jobs.values()].filter(job => job.indegree === 0).map(job => job.id);
  const order = [], ready = [], blocked = [];
  let visited = 0;
  while (available.length) {
    available.sort((a, b) => compare(b, a));
    const job = jobs.get(available.pop());
    visited++;
    if (job.state === 'pending') {
      if (job.causes.size) {
        blocked.push({ id: job.id, causes: [...job.causes].sort(compare) });
      } else {
        order.push(job.id);
        if ([...job.deps].every(dep => jobs.get(dep).state === 'succeeded')) ready.push(job.id);
      }
    }
    // Propagate all failed ancestry, regardless of this intermediate job's state.
    if (job.state === 'failed') job.causes.add(job.id);
    for (const id of job.children) {
      const child = jobs.get(id);
      for (const cause of job.causes) child.causes.add(cause);
      if (--child.indegree === 0) available.push(id);
    }
  }
  if (visited !== jobs.size) throw new Error('Dependency cycle');
  ready.sort(compare);
  blocked.sort((a, b) => compare(a.id, b.id));
  return { order, ready, blocked };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const plan = planJobs(JSON.parse(readFileSync(process.argv[2], 'utf8')));
    process.stdout.write(JSON.stringify(plan) + '\n');
  } catch (error) {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n');
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('full graph ordering, exact IDs, and immutable input', () => {
  const spec = [job('a', ['z']), job('b'), job('z', [], 'succeeded')];
  for (const item of spec) { Object.freeze(item.deps); Object.freeze(item); }
  Object.freeze(spec);
  assert.deepEqual(planJobs(spec), { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] });
  const ids = ['__proto__', 'constructor', 'é', 'Z', 'a', ' ', '😀', '\ue000'];
  const sorted = [...ids].sort();
  assert.deepEqual(planJobs(ids.map(id => ({ ...job(id), ignored: 123 }))), {
    order: sorted, ready: sorted, blocked: [],
  });
  assert.deepEqual(planJobs([job('constructor', ['__proto__']), job('__proto__')]), {
    order: ['__proto__', 'constructor'], ready: ['__proto__'], blocked: [],
  });
});

test('all failed ancestry survives failed and succeeded intermediates', () => {
  const spec = [job('root', [], 'failed'), job('second', ['root'], 'failed'),
    job('success', ['second'], 'succeeded'), job('x', ['success', 'root']),
    job('y', ['x', 'second']), job('free'), job('later', ['free'])];
  const expected = { order: ['free', 'later'], ready: ['free'], blocked: [
    { id: 'x', causes: ['root', 'second'] }, { id: 'y', causes: ['root', 'second'] },
  ] };
  assert.deepEqual(planJobs(spec), expected);
  assert.deepEqual(planJobs([...spec].reverse()), expected);
});

test('rejects malformed fields, references, duplicates and cycles synchronously', () => {
  const invalid = [null, {}, '[]', [null], [[]], [1], [{}],
    [{ id: '', deps: [], state: 'pending' }],
    [{ id: 1, deps: [], state: 'pending' }],
    [{ id: 'x', state: 'pending' }],
    [{ id: 'x', deps: null, state: 'pending' }],
    [{ id: 'x', deps: 'x', state: 'pending' }],
    [{ id: 'x', deps: [] }],
    [{ id: 'x', deps: [], state: 'Pending' }],
    [{ id: 'x', deps: [], state: new String('pending') }],
    [job('x', [''])], [job('x', [1])], [job('x', [null])],
    [job('x', ['missing'])], [job('x'), job('x')],
    [job('x'), job('y', ['x', 'x'])], [job('x', ['x'])],
    [job('ok'), job('x', ['y'], 'succeeded'), job('y', ['x'], 'failed')]];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
  assert.throws(() => planJobs(new Array(1)), Error);
  assert.throws(() => planJobs([job('x', new Array(1))]), Error);
});

test('CLI success, errors and silent import', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-test-'));
  const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));
  const run = args => spawnSync(process.execPath, args, { encoding: 'utf8' });
  try {
    const valid = join(dir, 'valid.json');
    const malformed = join(dir, 'malformed.json');
    const badGraph = join(dir, 'graph.json');
    writeFileSync(valid, JSON.stringify([job('é')]));
    writeFileSync(malformed, '{');
    writeFileSync(badGraph, JSON.stringify([job('x', ['x'])]));
    const success = run([cli, valid]);
    assert.equal(success.status, 0);
    assert.equal(success.stderr, '');
    assert.equal(success.stdout, JSON.stringify({ order: ['é'], ready: ['é'], blocked: [] }) + '\n');
    for (const args of [[], [valid, valid], [join(dir, 'absent')], [dir], [malformed], [badGraph]]) {
      const result = run([cli, ...args]);
      assert.equal(result.status, 2);
      assert.equal(result.stdout, '');
      assert.ok(result.stderr.trim());
    }
    const imported = run(['--input-type=module', '-e', `import ${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)};`]);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

